/**
 * TESTS:
 * - depthMatchesPyTorch: the exported Depth Anything V2 Metric Outdoor Small reproduces the PyTorch depth (metres) of
 *   its stored reference image
 * - segmentationMatchesPyTorch: the exported UperNet ConvNeXt-Base (ADE20K) reproduces the PyTorch class logits of its
 *   reference image, and the per-pixel argmax (the class) agrees
 *
 * The graphs and references are generated by the scripts in scripts/landscape/ into build/models/ (not in the
 * repository); the tests skip without them.
 **/

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>

#include "klartraum/computegraph/computegraph.hpp"
#include "klartraum/computegraph/tensorelement.hpp"
#include "klartraum/headless_frontend.hpp"
#include "klartraum/onnx/onnx_network.hpp"

using namespace klartraum;

namespace {

const std::string kSegmentation = "./build/models/semseg/onnx/upernet_convnext_base_ade20k_512x896";
const std::string kDepth = "./build/models/depth/onnx/depth_anything_v2_metric_outdoor_small_518x924";

std::vector<float> readFloats(const std::string& path) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    std::vector<float> data(static_cast<size_t>(file.tellg()) / sizeof(float));
    file.seekg(0);
    file.read(reinterpret_cast<char*>(data.data()), static_cast<std::streamsize>(data.size() * sizeof(float)));
    return data;
}

// Runs the graph `<name>.onnx` on `<name>_input_f32.bin` and returns its output `outputName`.
std::vector<float> run(const std::string& name, const std::string& inputName, const std::string& outputName,
                       const std::vector<uint32_t>& inputShape) {
    HeadlessFrontend frontend;
    auto& vc = frontend.getKlartraumEngine().getVulkanContext();
    auto network = vc.create<OnnxNetwork>(name + ".onnx");
    network->retainTensor(outputName);
    auto input = vc.create<TensorElement<float>>(inputShape);
    network->setInputTensor(inputName, input, -1);
    ComputeGraph graph(vc, 1);
    graph.compileFrom(network);
    input->getDataBuffer(0).memcopyFrom(readFloats(name + "_input_f32.bin"));
    graph.submitAndWait(vc.getGraphicsQueue(), 0);
    auto output = std::dynamic_pointer_cast<TensorElement<float>>(network->getOutputElement(outputName));
    EXPECT_NE(output, nullptr);
    if (!output)
        return {};
    std::vector<float> values(output->getDataElementCount());
    output->getDataBuffer(0).memcopyTo(values);
    return values;
}

} // namespace

TEST(LandscapeNetworksTest, depthMatchesPyTorch) {
    if (!std::filesystem::exists(kDepth + ".onnx"))
        GTEST_SKIP() << "run scripts/landscape/export_depth.py first";
    const auto actual = run(kDepth, "image", "depth", {1, 3, 518, 924});
    const auto expected = readFloats(kDepth + "_output_f32.bin");
    ASSERT_EQ(actual.size(), expected.size());
    float worst = 0.0f;
    double sum = 0.0;
    for (size_t i = 0; i < actual.size(); ++i) {
        const float relative = std::abs(actual[i] - expected[i]) / std::max(expected[i], 0.1f);
        worst = std::max(worst, relative);
        sum += relative;
    }
    std::cout << "relative depth error: worst " << worst << ", mean " << sum / actual.size() << std::endl;
    EXPECT_LT(worst, 1e-2f);
    EXPECT_LT(sum / actual.size(), 1e-3);
}

TEST(LandscapeNetworksTest, segmentationMatchesPyTorch) {
    if (!std::filesystem::exists(kSegmentation + ".onnx"))
        GTEST_SKIP() << "run scripts/landscape/export_semseg.py first";
    const auto actual = run(kSegmentation, "image", "logits", {1, 3, 512, 896});
    const auto expected = readFloats(kSegmentation + "_output_f32.bin");
    ASSERT_EQ(actual.size(), expected.size());
    constexpr size_t classes = 150, pixels = 128 * 224;
    float worst = 0.0f, largest = 0.0f;
    for (size_t i = 0; i < actual.size(); ++i) {
        worst = std::max(worst, std::abs(actual[i] - expected[i]));
        largest = std::max(largest, std::abs(expected[i]));
    }
    size_t agreeing = 0;
    for (size_t p = 0; p < pixels; ++p) {
        size_t a = 0, e = 0;
        for (size_t c = 1; c < classes; ++c) {
            if (actual[c * pixels + p] > actual[a * pixels + p])
                a = c;
            if (expected[c * pixels + p] > expected[e * pixels + p])
                e = c;
        }
        agreeing += a == e;
    }
    std::cout << "logit error " << worst << " of " << largest << ", argmax agreement " << 100.0 * agreeing / pixels
              << " %" << std::endl;
    EXPECT_LT(worst, 1e-3f * largest);
    EXPECT_GT(double(agreeing) / pixels, 0.999);
}
